function isStarterTopicId(topicId) {
  return STARTER_TOPICS.some((topic) => topic.id === topicId);
}
function getOrderedStarterTopics() {
  const order = new Map(STARTER_TOPIC_DISPLAY_ORDER.map((id, index2) => [id, index2]));
  return [...STARTER_TOPICS].sort((left, right) => (order.get(left.id) ?? Number.MAX_SAFE_INTEGER) - (order.get(right.id) ?? Number.MAX_SAFE_INTEGER));
}
function getVisibleStarterTopics() {
  const orderedTopics = getOrderedStarterTopics();
  if (typeof window === "undefined") return orderedTopics;
  let completedIds = [];
  try {
    const stored = JSON.parse(window.localStorage.getItem(STARTER_COMPLETED_STORAGE_KEY) || "[]");
    if (Array.isArray(stored)) completedIds = stored.filter((value) => typeof value === "string");
  } catch {
    completedIds = [];
  }
  const completed = new Set(completedIds);
  return orderedTopics.map((topic) => completed.has(topic.id) ? { ...topic, status: "done" } : topic);
}
function markStarterTopicCompleted(topicId) {
  if (typeof window === "undefined" || !isStarterTopicId(topicId)) return;
  const current = getVisibleStarterTopics().filter((topic) => topic.status === "done").map((topic) => topic.id);
  if (!current.includes(topicId)) current.push(topicId);
  window.localStorage.setItem(STARTER_COMPLETED_STORAGE_KEY, JSON.stringify(current));
}

