// native/content-style.ts
var scope = ".redflow-native :is(.rf-native-content,.rf-native-detail)";
var contentCss = `
${scope}{--iwt-shadow-dashboard-card:0 1px 3px rgba(30,41,59,.06);--iwt-shadow-dashboard-hover:0 3px 10px -5px rgba(30,41,59,.16)}
${scope} :is(.iwt-interactive-card,.iwt-pricing-card,.iwt-purchase-card):is(:hover,:focus-within){background:#fff;border-color:color-mix(in srgb,var(--iwt-slate-500,#64748B) 40%,white);box-shadow:var(--iwt-shadow-dashboard-hover);transform:none}
${scope} :is(.iwt-interactive-card,.iwt-pricing-card,.iwt-purchase-card):focus-within{border-color:var(--iwt-slate-500,#64748B)}
${scope} :is(.iwt-icon-action,.iwt-btn-secondary):is(:hover,:focus-visible){background:var(--iwt-slate-100,#F1F5F9);border-color:var(--iwt-slate-500,#64748B);color:var(--iwt-slate-900,#1E293B);box-shadow:none;transform:none}
${scope} .iwt-pricing-action:is(:hover,:focus-visible){background:var(--iwt-slate-900,#1E293B);border-color:var(--iwt-slate-900,#1E293B);color:white;box-shadow:none;transform:none}
`;

// native/radius-style.ts
var ui = ".redflow-native :where(:not(.rf-native-preview-device,.rf-native-preview-device *))";
var radiusCss = `
.redflow-native{--rf-radius-small:8px;--rf-radius-control:12px;--rf-radius-surface:16px;--rf-radius-check:4px;--rf-radius-circle:9999px}
${ui}:is(.rounded,.rounded-sm,.rounded-md,.rounded-lg,.rounded-xl){border-radius:var(--rf-radius-small)!important}
${ui}:is(.rounded-2xl,.rounded-pill){border-radius:var(--rf-radius-control)!important}
${ui}:is(.rounded-3xl,.rounded-card,.rounded-iwt-card,.rounded-iwt-hero,[class~="rounded-[10px]"],[class~="rounded-[12px]"],.iwt-card,.iwt-interactive-card,.iwt-pricing-card,.iwt-purchase-card){border-radius:var(--rf-radius-surface)!important}
${ui}:is(button,input:not([type=checkbox]):not([type=radio]):not([type=range]):not([type=color]),textarea,select,[role=combobox],a[class*="rounded"],.iwt-field-shell,.iwt-floating-field){border-radius:var(--rf-radius-control)!important}
${ui}:is(button.iwt-card,button.iwt-interactive-card){border-radius:var(--rf-radius-surface)!important}
${ui}:is(span.rounded-pill,[role=tooltip]){border-radius:var(--rf-radius-small)!important}
${ui}:is([role=menuitem],[role=menuitemcheckbox],[role=menuitemradio],[role=option]){border-radius:var(--rf-radius-control)!important}
${ui}:is([role=tablist],.iwt-segmented-control){border-radius:var(--rf-radius-control)!important}
.redflow-native :is([role=tablist],.iwt-segmented-control)>:is(button,span):not(.rf-native-preview-device *){border-radius:var(--rf-radius-small)!important}
${ui}:is([role=menu],[role=listbox],[role=dialog]:not([aria-label="\u914D\u56FE\u9884\u89C8"])){border-radius:var(--rf-radius-surface)!important}
.redflow-native .rf-native-brand-select~div button{border-radius:var(--rf-radius-control)!important}
${ui}:is([role=checkbox],input[type=checkbox],[class~="rounded-[2px]"]){border-radius:var(--rf-radius-check)!important}
${ui}:is([role=radio],input[type=radio],[role=switch],.rounded-full:not(button),.rf-native-avatar,span.rounded-pill.h-2.w-2,span.rounded-pill.h-5.w-5){border-radius:var(--rf-radius-circle)!important}
`;

// native/dialog-style.ts
var dialogCss = `
.redflow-native .rf-native-scrim{background-color:rgba(0,0,0,.36);-webkit-backdrop-filter:none;backdrop-filter:none}
.redflow-native .rf-native-lightbox>button,.redflow-native .rf-native-lightbox>div{background:white;color:var(--iwt-slate-900,#1E293B);border-color:var(--iwt-slate-100,#F1F5F9);-webkit-backdrop-filter:none;backdrop-filter:none}
.redflow-native .rf-native-lightbox>button:hover:not(:disabled){background:var(--iwt-slate-100,#F1F5F9);color:var(--iwt-slate-900,#1E293B)}
.redflow-native .rf-native-lightbox>button:focus-visible{outline:2px solid var(--iwt-slate-700,#334155);outline-offset:2px}
.redflow-native .rf-native-dialog{display:flex!important;flex-direction:column;gap:0!important;width:calc(100% - 32px);max-height:min(900px,calc(100dvh - 64px));padding:0!important;overflow:hidden!important;background:white}
.redflow-native .rf-native-dialog-header{flex:0 0 auto;margin:0!important;padding:20px 64px 16px 24px;border-bottom:1px solid var(--iwt-slate-100,#F1F5F9);background:white;text-align:left}
.redflow-native .rf-native-dialog-body{flex:1 1 auto;min-height:0;min-width:0;margin:0!important;padding:20px 24px;overflow-y:auto;overscroll-behavior:contain;scrollbar-gutter:stable}
.redflow-native .rf-native-dialog-footer{flex:0 0 auto;margin:0!important;padding:16px 24px;border-top:1px solid var(--iwt-slate-100,#F1F5F9);background:white;flex-wrap:wrap;gap:8px}
.redflow-native button.rf-native-close{display:inline-flex;align-items:center;justify-content:center;flex:none;box-sizing:border-box;width:40px;height:40px;padding:0;color:var(--iwt-slate-700,#334155);opacity:1}
.redflow-native button.rf-native-close svg{width:16px;height:16px;pointer-events:none}
.redflow-native button.rf-native-close:hover{background:var(--iwt-slate-100,#F1F5F9);color:var(--iwt-slate-900,#1E293B)}
.redflow-native button.rf-native-close:focus-visible{outline:2px solid var(--iwt-slate-500,#64748B);outline-offset:2px}
.redflow-native .rf-native-dialog>.rf-native-close{top:8px;right:12px;z-index:2}
@media(max-width:640px),(max-height:600px){
 .redflow-native .rf-native-dialog{width:calc(100% - 24px);max-height:calc(100dvh - 32px)}
 .redflow-native .rf-native-dialog>.rf-native-close{top:2px;right:8px}
 .redflow-native .rf-native-dialog-header{padding:12px 56px 12px 16px}
 .redflow-native .rf-native-dialog-body{padding:16px}
 .redflow-native .rf-native-dialog-footer{padding:12px 16px}
}
`;

// native/frame-style.ts
var frameCss = `
.redflow-native.rf-native-panel{height:100%;min-height:0;min-width:0;overflow:hidden;position:relative;isolation:isolate;--rf-sidebar-width:208px;--rf-content-top-inset:16px;container-type:inline-size;container-name:rf-panel;box-sizing:border-box;background:white}
.redflow-native .rf-native-state{margin:0;min-width:0;padding:16px 20px;line-height:1.5;overflow-wrap:anywhere}
html[data-platform="darwin"] .redflow-native .rf-native-state{padding-inline-start:max(20px,var(--dsh-frame-leading-clearance,0px))}
.redflow-native .rf-native-route-stack{position:relative;height:100%;min-height:0;overflow:hidden}
.redflow-native .rf-native-route-base{height:100%;min-height:0;position:relative;isolation:isolate}
.redflow-native .rf-native-detail-layer{position:absolute;inset:0 0 0 var(--rf-sidebar-width);z-index:40;container-type:inline-size;container-name:rf-detail;background:white;outline:none;box-shadow:none;animation:rf-detail-enter 280ms cubic-bezier(.22,.68,0,1) both;will-change:transform}
/* Let the open account menu cross the desktop sidebar boundary above the detail. */
@container rf-panel (width > 760px){
 .redflow-native .rf-native-route-base:has(.rf-native-user-menu>button[aria-expanded="true"]){isolation:auto}
 .redflow-native .rf-native-sidebar-frame:has(.rf-native-user-menu>button[aria-expanded="true"]){z-index:41}
}
.redflow-native .rf-native-detail-layer[data-motion="exit"]{animation:rf-detail-exit 240ms cubic-bezier(.4,0,.2,1) both;pointer-events:none}
.redflow-native .rf-native-detail-layer .iwt-detail-push-in{animation:none;transform:none;opacity:1}
@keyframes rf-detail-enter{from{transform:translateX(100%)}to{transform:translateX(0)}}
@keyframes rf-detail-exit{from{transform:translateX(0)}to{transform:translateX(100%)}}
@media(prefers-reduced-motion:reduce){.redflow-native .rf-native-detail-layer{animation:none!important;transform:none!important}}
.redflow-native .rf-native-shell{height:100%;min-height:0;min-width:0;overflow:hidden}
.redflow-native .rf-native-body{display:flex;flex:1;min-width:0;min-height:0;overflow:hidden;position:relative}
.redflow-native .rf-native-content{padding-top:var(--rf-content-top-inset);box-sizing:border-box;display:flex;flex:1;flex-direction:column;min-width:0;min-height:0;overflow:hidden}
.redflow-native .rf-native-scroll{flex:1;min-height:0;min-width:0;overflow:auto;overscroll-behavior:contain}
.redflow-native .rf-native-mobile-header{display:none;flex:none;position:relative;z-index:20;min-width:0}
.redflow-native .rf-native-sidebar-frame{flex:none;width:var(--rf-sidebar-width);min-width:0;min-height:0;position:relative}
.redflow-native .rf-native-sidebar-frame>aside{position:relative;inset:auto;height:100%;width:100%;transform:none;min-height:0;box-sizing:border-box;padding-top:max(48px,var(--dsh-frame-top-clearance,0px));background:var(--iwt-slate-100,#F1F5F9);backdrop-filter:none;border-right-color:color-mix(in srgb,var(--iwt-slate-500,#64748B) 20%,transparent)}
.redflow-native .rf-native-sidebar-frame>div:first-child{display:none}
.redflow-native .rf-native-sidebar-frame>aside>div:first-child{display:flex;min-height:64px;flex-shrink:0}
.redflow-native .rf-native-sidebar-frame>aside>div:first-child>div{min-width:0;gap:8px}
.redflow-native .rf-native-sidebar-frame>aside>div:first-child>div>span{font-size:14px;line-height:1.5;white-space:normal}
.redflow-native .rf-native-sidebar-frame>aside>div:first-child>div>button{flex-shrink:0}
.redflow-native .rf-native-sidebar-frame>aside>div:first-child>button{display:none}
.redflow-native .rf-native-sidebar-frame>aside>div:first-child{padding-inline:12px}
.redflow-native .rf-native-brand-name{display:flex;flex-direction:column;gap:1px;min-width:0}
.redflow-native .rf-native-brand-name>span{display:block;white-space:nowrap}
.redflow-native .rf-native-brand-subtitle{font-size:13px;font-weight:400;color:var(--iwt-slate-500,#64748B)}
.redflow-native .rf-native-sidebar-frame>aside>nav{padding-inline:8px}
.redflow-native .rf-native-sidebar-frame>aside>div:last-child{padding-inline:8px}
.redflow-native .rf-native-sidebar-frame>aside>div:last-child>div{padding-inline:0;gap:4px}
.redflow-native .rf-native-sidebar-frame button[title="\u67E5\u770B\u79EF\u5206\u8D26\u6237"]{padding-inline:6px;white-space:nowrap;font-size:13px}

.redflow-native .rf-native-sidebar-frame :is(button,a),.redflow-native .rf-native-mobile-header :is(button,a){-webkit-app-region:no-drag}
.redflow-native .rf-native-detail{padding-top:var(--rf-content-top-inset);box-sizing:border-box;height:100%;overflow:hidden;overscroll-behavior:contain}
.redflow-native .rf-native-detail>.iwt-detail-push-in{padding-top:0}
.redflow-native .rf-native-detail>.iwt-detail-push-in>div:first-child{position:sticky;top:0;z-index:20;min-height:80px;padding-top:24px;padding-bottom:20px;background:white}
.redflow-native .rf-native-detail-trail{display:flex;align-items:center;justify-content:flex-start;flex-wrap:wrap;gap:8px 16px;min-width:0;text-align:left;font-size:14px;font-weight:400;line-height:20px}
.redflow-native .rf-native-detail-trail button{display:inline-flex;align-items:center;justify-content:flex-start;gap:6px;min-height:36px;padding:8px 12px;font-size:inherit;font-weight:400;line-height:20px;border-radius:var(--rf-radius-control);color:var(--iwt-slate-500,#64748B);background:transparent;transition:color .15s,background-color .15s}
.redflow-native .rf-native-detail-trail button:hover{color:var(--iwt-slate-700,#334155);background:var(--iwt-slate-100,#F1F5F9)}
.redflow-native .rf-native-detail-trail button:focus-visible{outline:2px solid var(--iwt-slate-500,#64748B);outline-offset:3px}
.redflow-native .rf-native-detail-trail nav{font-size:12px;line-height:18px}
.redflow-native .rf-native-detail-trail nav button{line-height:18px;min-height:28px;padding:4px}
.redflow-native .rf-native-detail-trail ol{display:flex;align-items:center;flex-wrap:wrap;gap:4px;margin:0;padding:0;list-style:none;color:var(--iwt-slate-500,#64748B)}
.redflow-native .rf-native-detail-trail [aria-current="page"]{color:var(--iwt-slate-500,#64748B);font-weight:400}
.redflow-native .rf-native-detail-trail li[aria-hidden="true"]{color:var(--iwt-slate-500,#64748B);opacity:.6;font-weight:400;user-select:none}
@container rf-panel (max-width:760px){
 html[data-platform="darwin"] .redflow-native .rf-native-detail>.iwt-detail-push-in>div:first-child{padding-inline-start:max(0px,calc(var(--dsh-frame-leading-clearance,0px) - 16px))}
}
.redflow-native .rf-native-sidebar-frame button.rf-native-brand-select:is(:hover,:focus,:focus-visible,[data-state="open"]){border-color:var(--iwt-slate-500,#64748B)!important;box-shadow:none!important;outline:none!important}
.redflow-native .rf-native-sidebar-frame nav a:not([aria-current="page"]):hover,.redflow-native .rf-native-sidebar-frame a[href]:hover{background:rgba(255,255,255,.8);color:var(--iwt-slate-900,#1E293B)}
.redflow-native .rf-native-sidebar-frame a[href][aria-current="page"]{background:var(--iwt-slate-900,#1E293B);color:white}
.redflow-native .rf-native-sidebar-frame a[href]:focus-visible{--tw-ring-color:var(--iwt-slate-500,#64748B)}
@container(max-width:900px){
 .redflow-native .rf-native-detail-layer>.iwt-detail-push-in>.grid{grid-template-columns:minmax(0,1fr)}
}
@container(max-width:760px){
 .redflow-native .rf-native-detail-layer{inset-inline-start:0}

 .redflow-native .rf-native-mobile-header{display:block}
 .redflow-native .rf-native-mobile-header>header{display:flex;height:56px;min-height:56px;min-width:0;background:var(--iwt-slate-100,#F1F5F9);backdrop-filter:none;gap:8px}
 .redflow-native .rf-native-mobile-header>header>div{min-width:0;flex:1;gap:8px}
 .redflow-native .rf-native-mobile-header>header>div>button{flex-shrink:0}
 .redflow-native .rf-native-mobile-header>header>div>span{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
 html[data-platform="darwin"] .redflow-native .rf-native-mobile-header>header{padding-inline-start:max(16px,var(--dsh-frame-leading-clearance,0px))}
 .redflow-native .rf-native-sidebar-frame{position:absolute;inset:56px 0 0;width:100%;z-index:30;pointer-events:none;overflow:hidden}
 .redflow-native .rf-native-sidebar-frame[data-mobile-open="true"]{pointer-events:auto}
 .redflow-native .rf-native-sidebar-frame>div:first-child{display:block;position:absolute;inset:0;width:100%;height:100%}
 .redflow-native .rf-native-sidebar-frame>aside{padding-top:0;position:absolute;inset:0 auto 0 0;height:100%;width:min(224px,calc(100% - 24px));max-width:100%;transform:translateX(-100%);visibility:hidden;transition:transform .2s ease,visibility .2s}
 .redflow-native .rf-native-sidebar-frame[data-mobile-open="true"]>aside{transform:translateX(0);visibility:visible}
 .redflow-native .rf-native-sidebar-frame>aside>div:first-child{display:flex;min-height:64px;flex-shrink:0}
 .redflow-native .rf-native-sidebar-frame>aside>div:first-child>button{display:inline-flex}
 .redflow-native .rf-native-sidebar-frame>aside>div:first-child>div{min-width:0}
 .redflow-native .rf-native-sidebar-frame>aside>div:first-child>div>span{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
 .redflow-native .rf-native-detail>.iwt-detail-push-in{padding-inline:16px}
}
@container(max-width:320px){.redflow-native .rf-native-mobile-header>header>div>span{display:none}.redflow-native .rf-native-mobile-header>header>div{flex:none}}
/* Toolbar stays visible; only the content column scrolls beside the preview. */
.redflow-native .rf-native-detail-shell{display:flex;flex-direction:column;height:100%;min-height:0;padding-bottom:20px}
.redflow-native .rf-native-detail-toolbar{flex:0 0 auto;margin-bottom:0;align-items:center;gap:12px 24px}
.redflow-native .rf-native-detail-toolbar>div{align-items:center}
.redflow-native .rf-native-detail-toolbar>div:last-child :is(button,a){display:inline-flex;align-items:center;justify-content:center;min-height:36px;padding:8px 12px;font-size:14px;line-height:20px}
.redflow-native .rf-native-detail-columns{flex:1;min-height:0;grid-template-columns:minmax(0,1fr);overflow:auto;overscroll-behavior:contain;align-content:start}
.redflow-native .rf-native-detail-copy-scroll{min-width:0;min-height:0}
.redflow-native .rf-native-detail-preview{position:static;min-width:0}
@container rf-detail (min-width:901px){
 .redflow-native .rf-native-detail-columns{grid-template-columns:minmax(0,1fr) 360px;overflow:hidden;align-content:stretch;grid-template-rows:minmax(0,1fr)}
 .redflow-native .rf-native-detail-copy-scroll{overflow-y:auto;overscroll-behavior:contain;scrollbar-gutter:stable;padding:2px 4px 12px 2px}
 .redflow-native .rf-native-detail-preview{height:100%;min-height:0;align-self:stretch;overflow:hidden;container-type:size}
 .redflow-native .rf-native-detail-preview>.iwt-card{height:100%;box-sizing:border-box}
 .redflow-native .rf-native-detail-preview .rf-native-preview-device{width:min(300px,calc((100cqh - 140px)*.45995))}
}
@media(max-height:600px){
 .redflow-native .rf-native-detail-columns{overflow:auto;grid-template-rows:auto;align-content:start}
 .redflow-native .rf-native-detail-copy-scroll{overflow:visible}
 .redflow-native .rf-native-detail-preview{height:auto;overflow:visible;container-type:normal;align-self:start}
 .redflow-native .rf-native-detail-preview>.iwt-card{height:auto}
 .redflow-native .rf-native-detail-preview .rf-native-preview-device{width:100%}
}
/* Workbench panels use available plugin space, not the host window height. */
.redflow-native .rf-native-workbench{min-height:100%;box-sizing:border-box;padding-bottom:16px}
.redflow-native .rf-native-workbench-grid{grid-template-columns:minmax(0,1fr)}
.redflow-native .rf-native-workbench-grid>.iwt-card{height:auto;max-height:none;min-height:0;min-width:0}
@container rf-panel (min-width:1000px){
 .redflow-native .rf-native-workbench{height:100%;display:flex;flex-direction:column;min-height:0;overflow:hidden}
 .redflow-native .rf-native-workbench>div:first-child{flex:none}
 .redflow-native .rf-native-workbench-result{display:flex;flex:1;min-height:0}
 .redflow-native .rf-native-workbench-grid{display:grid;flex:1;min-height:0;min-width:0;grid-template-columns:repeat(2,minmax(0,1fr));grid-template-rows:minmax(0,1fr)}
 .redflow-native .rf-native-workbench-grid>.iwt-card{height:100%;max-height:none;overflow:hidden}
 .redflow-native .rf-native-workbench-grid>.iwt-card>div{min-height:0;overscroll-behavior:contain}
}
${contentCss}
.redflow-native .rf-native-collection-action {
 display:inline-flex;align-items:center;justify-content:center;box-sizing:border-box;
 height:32px;padding:0 12px;gap:6px;white-space:nowrap;
 font-size:11px;font-weight:500;line-height:16px;border-width:1px;border-style:solid;
}
.redflow-native .rf-native-collection-action.iwt-control-primary{border-color:transparent}
.redflow-native .rf-native-task-primary{background:var(--iwt-slate-900,#1E293B);color:white;border-color:var(--iwt-slate-900,#1E293B)}
.redflow-native .rf-native-task-primary:hover{background:var(--iwt-slate-700,#334155);color:white;border-color:var(--iwt-slate-700,#334155)}
.redflow-native .rf-native-task-pagination{margin-top:24px}
.redflow-native .rf-native-task-pagination nav{display:flex;align-items:center;justify-content:flex-end;flex-wrap:wrap;gap:8px;font-size:13px;color:var(--iwt-slate-500,#64748B)}
.redflow-native .rf-native-task-pagination button{min-width:32px;min-height:32px;padding:4px 10px;border:1px solid var(--iwt-slate-100,#F1F5F9);border-radius:var(--rf-radius-control);background:white;color:var(--iwt-slate-700,#334155)}
.redflow-native .rf-native-task-pagination button:hover:not(:disabled){background:var(--iwt-slate-100,#F1F5F9)}
.redflow-native .rf-native-task-pagination button[aria-current="page"]{background:var(--iwt-slate-900,#1E293B);color:white}
.redflow-native .rf-native-task-pagination button:disabled{opacity:.45;cursor:not-allowed}
.redflow-native .rf-native-task-pagination button:focus-visible{outline:2px solid var(--iwt-slate-500,#64748B);outline-offset:2px}
.redflow-native .rf-native-task-pagination [role="alert"]{color:#b91c1c;margin-bottom:12px;font-size:13px}

.redflow-native .rf-native-task-page{container-type:inline-size;container-name:rf-task-page}
.redflow-native .rf-native-task-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
@container rf-task-page (min-width:640px){.redflow-native .rf-native-task-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}
@container rf-task-page (min-width:880px){.redflow-native .rf-native-task-grid{grid-template-columns:repeat(4,minmax(0,1fr))}}
.redflow-native .rf-native-source-error{color:#b91c1c}
${dialogCss}
${radiusCss}
@media(prefers-reduced-motion:reduce){.redflow-native .rf-native-sidebar-frame>aside{transition:none}}
`;

